#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main() {
    srand(time(NULL)); // seed the rand function with current time

    int a = 1000 + (rand() % 9000); // generate a number between 1000 and 10000
    int b = 1000 + (rand() % 9000); // generate a number between 1000 and 10000
    int c = 1000 + (rand() % 9000); // generate a number between 1000 and 10000

    printf("a: %d\n", a);
    printf("b: %d\n", b);
    printf("c: %d\n", c);

    int sum = a + b + c;
    long long sum2 = (long long)a + b + c; // cast to long long before adding

    printf("sum: %d\n", sum);
    printf("sum2: %lld\n", sum2); // format specifier for long long is '%lld'

    return 0;
}
```
Please note that the result of the addition operation to get 'sum2', which has been casted to a `long long`, will depend on whether or not the system supports this data type. If it doesn't, an overflow error can occur and incorrect results might be outputted.
