    int sales[12] = {0}; // array to hold monthly sales

    // Get sales for each month
    for (int i = 0; i < 12; ++i) {
        sales[i] = getMonthlySales();
    }

    // Calculate quarterly sales and print them
    for (int i = 0; i < 4; ++i) {
        int total_sales = 0;
