```python
from flask import Flask, send_file, request
import os
app = Flask(__name__)

def trigger_url(url):
    def decorator(func):
        @app.route(url)
        def wrapper(*args, **kwargs):
            return func()
        return wrapper
    return decorator

@trigger_url('/image/<string:file>')
def send_image():
    file = request.view_args['file']  # get the file name from url
    directory = os.path.join(app.root_path, 'images')
    file_path = os.path.join(directory, file)

    if os.path.isfile(file_path):  # check if the file exists in images folder
        return send_file(file_path, mimetype='image/jpeg')  # sends the file to browser
    else:
        return "File not found", 404

if __name__ == '__main__':
    app.run()
```
To test this code, you can navigate to http://localhost:5000/image/{your_file_name} in your browser and it will attempt to send the file from your images directory. Replace {your_file_name} with the name of any image file located in your 'images' folder.

