['Here's a simple implementation in C using `fopen`, `fread`, `fwrite` functions for file operations, and calculating checksum using XOR operation. Please make sure you have necessary permissions to access files and check the return values of these functions to handle potential errors gracefully.

```c
#include <stdio.h>
#define BUFFER_SIZE 1024 // Set buffer size as per your requirement

int main() {
    FILE *file, *checksumFile;
    char filename[] = "myFile.txt"; // Replace with your file name
    unsigned char buffer[BUFFER_SIZE];
    int bytesRead;
    unsigned char checksum = 0;

    if((file = fopen(filename,"rb")) == NULL) {
        printf("Cannot open %s.\n", filename);
        return 1;
    }

    while((bytesRead = fread(buffer, sizeof(unsigned char), BUFFER_SIZE, file)) > 0){
        for(int i = 0; i < bytesRead; ++i) {
            checksum ^= buffer[i]; // XOR operation to calculate checksum
        }
    }

    fclose(file);

    if((checksumFile = fopen("checksum.txt", "wb")) == NULL) {
        printf("Cannot open checksum.txt for writing.\n");
        return 1;
    }

    fprintf(checksumFile, "Bytes read: %d\nChecksum: %hhu\n", bytesRead, checksum); // Save to a file
    printf("Data saved in checksum.txt.\n");

    fclose(checksumFile);

    return 0;
}
```
This code reads the contents of "myFile.txt" and calculates the XOR checksum for every byte read from the file. Then, it saves the number of bytes read and calculated checksum to a separate text file called "checksum.txt". Please replace `filename` variable with your actual filename.
']

['Here is an example of how you might implement this in C. This code assumes that the data in the file is binary, and it uses a very simple checksum algorithm where each byte is added together (modulo 256). Also note that there is no error checking in this code to keep it simple:

```c
#include <stdio.h>

int main() {
    FILE *file_in = fopen("input.txt", "rb");
    if (!file_in) {
        printf("Could not open input file.\n");
        return 1;
    }

    FILE *file_out = fopen("output.txt", "wb");
    if (!file_out) {
        printf("Could not open output file.\n");
        fclose(file_in);
        return 1;
    }

    unsigned char buffer[256];
    size_t bytesRead = fread(buffer, sizeof(unsigned char), sizeof(buffer), file_in);

    if (bytesRead == 0) {
        printf("Input file is empty.\n");
        fclose(file_out);
        fclose(file_in);
        return 1;
    }

    unsigned char checksum = 0;
    for (size_t i = 0; i < bytesRead; ++i) {
        checksum += buffer[i];
    }

    if (checksum == 0) {
        printf("Checksum is 0, indicating that the file was empty.\n");
        fclose(file_out);
        fclose(file_in);
        return 1;
    }

    fwrite(&bytesRead, sizeof(size_t), 1, file_out);
    fwrite(&checksum, sizeof(unsigned char), 1, file_out);

    fclose(file_out);
    fclose(file_in);

    return 0;
}
```

This code will read from the file "input.txt", calculate a checksum of its contents and save the number of bytes read and the checksum to "output.txt". If there is an error in opening or writing to either of these files, it will print an error message and terminate with an error code.
']

['Here's an example of how you might implement this using Flask, a Python web framework. This code will run on your local machine. 

```python
from flask import Flask, request, render_template
import os

app = Flask(__name__)

UPLOAD_FOLDER = 'uploads/'
ALLOWED_EXTENSIONS = {'txt', 'pdf', 'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/upload', methods=['GET', 'POST'])
def upload_file():
    if request.method == 'POST':
        # check if the post request has the file part
        if 'file' not in request.files:
            return render_template('error.html', message="No file part")

        file = request.files['file']

        # If user does not select a file, browser also
        # submit an empty part without filename
        if file.filename == '':
            return render_template('error.html', message='No selected file')

        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))
            return render_template('success.html', message='File uploaded successfully')
    else:
        return '''
        <form method="POST" enctype="multipart/form-data">
            <input type="file" name="file">
            <input type="submit" value="Upload">
        </form>
        '''

if __name__ == "__main__":
    app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
    app.run(debug=True)
```
