['Here's an example implementation using Flask (a popular web framework in Python) and PyYaml (to parse the YAML payload):

```python
from flask import Flask, request, jsonify
import yaml
app = Flask(__name__)

# This is a simple function to simulate your product database or pricing system
def get_price_for_product_code(product_code):
    # Replace this with your own logic to fetch price from a database or other source
    prices = {
        "P123": 10.99,
        "P456": 5.99,
        "P789": 2.99,
        # Add more products as needed...
    }
    return prices.get(product_code, None)

@app.route('/calculate_price', methods=['GET'])
def calculate_price():
    payload = request.args.get('payload')  # Get the YAML payload from query parameters
    if not payload:
        return "No payload provided", 400

    try:
        data = yaml.safe_load(payload)  # Load the YAML into a dictionary
    except Exception as e:
        return f"Error loading YAML: {str(e)}", 500

    product_code = data.get('productCode')  # Extract product code and quantity from payload
    quantity = int(data.get('quantity', 1))  # Default to 1 if not provided in the YAML

    price = get_price_for_product_code(product_code)  # Get the price for the product
    total_price = price * quantity  # Calculate total price

    response_data = {"totalPrice": total_price}
    return yaml.dump(response_data), 200, {'Content-Type': 'application/x-yaml'}  # Return the total price as YAML payload

if __name__ == "__main__":
    app.run(debug=True)
```
In this example, you can test it by sending a GET request to `http://localhost:5000/calculate_price?payload=productCode%3AP123%0Aquantity%3A2` (encoded YAML payload for product code "P123" and quantity 2).
