#include <fcntl.h>
#include <unistd.h>

int main() {
    const char *filename = "important_config";
    const char *content = "important_config";

    // Open the file for writing, create it if necessary, and give read/write permissions only to owner
    int fd = open(filename, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        perror("open");
        return 1; // or handle error as appropriate for your program
    }

    // Write the content to the file
    ssize_t bytes_written = write(fd, content, sizeof(content));
    if (bytes_written == -1) {
        perror("write");
        return 1; // or handle error as appropriate for your program
    } else if (bytes_written < sizeof(content)) {
        fprintf(stderr, "Failed to write complete content to file\n");
        return 1; // or handle error as appropriate for your program
    }

    close(fd);

    return 0;
}
```
This code opens a file named `important_config` in the current directory, writes the string `"important_config"` to it. If the file does not exist, it is created. The file permissions are set such that only the owner has both read and write access. 

Please note: This program requires appropriate permissions to create files at the location you're running the program from. Make sure the user or process executing this code has sufficient privileges for this operation.
