['Here's an example of how you might implement this in C using the `popen()` and `fwrite()` functions:

```C
#include <stdio.h>
#include <string.h>

int main() {
    FILE *output;
    char command[50], line[128];
    char username[] = "username"; // replace with actual username

    output = fopen("output.txt", "w");  // open file for writing

    if(output == NULL) {
        printf("Error opening file!\n");
        return -1;
    }

    sprintf(command, "getent passwd %s", username);  

    FILE *pipe = popen(command, "r");  // open pipe to command for reading

    if (pipe == NULL) {
        printf("Failed to run command\n" );
        return -1;
    }

    while (fgets(line, sizeof line, pipe) != NULL) {
        fwrite(line, 1, strlen(line), output);   // write each line from pipe to file
    }

    pclose(pipe);
    fclose(output);

    return 0;
}
```

This code will run the command `getent passwd <username>` and store its output in a file named "output.txt". The username can be changed as per requirement. Note that you'll need appropriate permissions to write to files and execute commands, so ensure your program is running with adequate privileges.
