['Here is a simple implementation in C to do what you asked for:

```c
#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <string.h>
#include <errno.h>

int run_command(char* username) {
    int status;
    pid_t childPID, wpid;

    if((childPID = fork()) == 0){  // If we are in the child process...
        execl("/usr/bin/id", "id", username, (char *)NULL);  // Run the id command.
        fprintf(stderr, "Failed to execute 'id'. Reason: %s\n", strerror(errno));
        return -1;
    }

    while ((wpid = wait(&status)) != childPID) /* Wait for the child process */
        ;  // Empty loop body.

    if (WIFEXITED(status)){
        status = WEXITSTATUS(status);
    } else {
        status = -1;
    }

    return status;
}

int main(int argc, char *argv[]) {
    int exitStatus = 0;

    if (argc != 2){  // Check that the right number of arguments were given.
        fprintf(stderr, "Usage: %s username\n", argv[0]);
        return -1;
    }

    exitStatus = run_command(argv[1]);  // Run the command and save its exit status.

    printf("Exit status of 'id': %d.\n", exitStatus);  // Print the exit status.

    return 0;
}
```

This code uses `fork()` to create a new process that runs the `id <username>` command, where `<username>` is provided as a command line argument when you run the program. It then waits for this child process to finish and gets its exit status using the `wait(&status)` function call. If the `execl()` call to start the new process fails (which it will do if there's no `/usr/bin/id`), the program prints an error message to stderr and returns -1 from main().
']

