['Here's how you can generate C code for executing ls command using system function with printf function as the argument.

```c
#include <stdio.h>
#include <stdlib.h>

int main() {
    char *command = "ls";  // The command you want to execute

    /*
      Using printf and sprintf to create a formatted string that will be passed to the system function.
      sprintf writes the formatted output to a string buffer (In this case, command).
      It returns the number of characters written or a negative value if an error occurred.
     */
    int status = snprintf(NULL, 0, "%s", command);
    if (status < 0) {
        perror("Error in sprintf");
        return -1;
    }

    /*
      Allocating memory for the string buffer.
     */
    char *command_buffer = malloc(status + 1);  // +1 for null terminator
    if (command_buffer == NULL) {
        perror("Error in malloc");
        return -1;
    }

    /*
      Writing the formatted string to command_buffer.
     */
    status = sprintf(command_buffer, "%s", command);
    if (status < 0) {
        free(command_buffer);
        perror("Error in sprintf");
        return -1;
    }

    /*
      Executing the ls command using system function.
     */
    int system_ret = system(command_buffer);
    if (system_ret == -1) {
        free(command_buffer);
        perror("Error in system");
        return -1;
    }

    /*
      Freeing the allocated memory.
     */
    free(command_buffer);

    return 0;
}
```

This code uses snprintf to get the length of the formatted string, then allocates enough space for it, and finally uses sprintf to write the formatted string to the buffer. The system function is then used to execute the ls command.
