['Here's an example of C code that does exactly what you specified:

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

// Function to trim trailing whitespace
void trimTrailingWhiteSpace(char *str) {
    char* end;

    // Trim leading space
    while(isspace((unsigned char)*str)) str++;

    if(*str == 0)  // All spaces?
        return;

    // Trim trailing space
    end = str + strlen(str) - 1;
    while(end > str && isspace((unsigned char)*end)) end--;

    // Write new null terminator character
    *++end = '\0';
}

int main(int argc, char **argv) {
    if (argc != 2) { 
        printf("Error: Please provide exactly one argument.\n"); 
        return EXIT_FAILURE;
    }

    // Get argument from command line and store it in a variable called input
    char *input = argv[1];

    // Print the argument
    printf("Input before trimming: %s\n", input);

    // Trim trailing whitespace
    trimTrailingWhiteSpace(input);

    // Print the argument again after trimming whitespaces.
    printf("Input after trimming: %s\n", input);

    return EXIT_SUCCESS; 
}
```
This C code first checks if there is exactly one command line argument provided by the user, and if not it exits with an error message. Then it gets the argument from the command line and stores it in a variable called `input`. After that, it prints out the original input. It then trims any trailing white space characters from this string using a helper function `trimTrailingWhiteSpace()`, which takes as parameter a pointer to the string to be trimmed. Finally, it prints out the string again after it has been trimmed and exits with success.
